
































































import { Component, Vue, Prop, Watch } from 'vue-property-decorator'
import { Form as ElForm } from 'element-ui'
import { editPassword } from '@/api/employee'
import { UserModule } from '@/store/modules/user'
import Cookies from 'js-cookie'

@Component({
  name: 'ChangePasswordModal'
})
export default class ChangePasswordModal extends Vue {
  @Prop({ type: Boolean, default: false }) visible!: boolean

  private dialogVisible = false
  private submitting = false

  private passwordForm = {
    oldPassword: '',
    newPassword: '',
    confirmPassword: ''
  }

  // 校验新密码
  private validateNewPassword = (rule: any, value: string, callback: Function) => {
    if (!value) {
      callback(new Error('请输入新密码'))
    } else if (value.length < 6) {
      callback(new Error('密码长度不能少于6位'))
    } else if (value === this.passwordForm.oldPassword) {
      callback(new Error('新密码不能与旧密码相同'))
    } else {
      // 如果确认密码已填写，需要重新校验确认密码
      if (this.passwordForm.confirmPassword) {
        (this.$refs.passwordForm as ElForm).validateField('confirmPassword')
      }
      callback()
    }
  }

  // 校验确认密码
  private validateConfirmPassword = (rule: any, value: string, callback: Function) => {
    if (!value) {
      callback(new Error('请再次输入新密码'))
    } else if (value !== this.passwordForm.newPassword) {
      callback(new Error('两次输入的密码不一致'))
    } else {
      callback()
    }
  }

  private passwordRules = {
    oldPassword: [
      { required: true, message: '请输入旧密码', trigger: 'blur' },
      { min: 6, message: '密码长度不能少于6位', trigger: 'blur' }
    ],
    newPassword: [
      { required: true, validator: this.validateNewPassword, trigger: 'blur' }
    ],
    confirmPassword: [
      { required: true, validator: this.validateConfirmPassword, trigger: 'blur' }
    ]
  }

  @Watch('visible', { immediate: true })
  onVisibleChange(val: boolean) {
    this.dialogVisible = val
  }

  @Watch('dialogVisible')
  onDialogVisibleChange(val: boolean) {
    if (!val) {
      this.$emit('update:visible', val)
    }
  }

  // 获取当前用户ID
  private getUserId(): number | string {
    try {
      const userInfo = Cookies.get('user_info')
      if (userInfo) {
        const parsed = typeof userInfo === 'string' ? JSON.parse(userInfo) : userInfo
        return parsed.id
      }
    } catch (e) {
      console.error('解析用户信息失败', e)
    }
    return ''
  }

  // 提交修改密码
  private handleSubmit() {
    (this.$refs.passwordForm as ElForm).validate(async (valid: boolean) => {
      if (!valid) return

      const empId = this.getUserId()
      if (!empId) {
        this.$message.error('获取用户信息失败，请重新登录')
        return
      }

      this.submitting = true
      try {
        const res = await editPassword({
          empId,
          oldPassword: this.passwordForm.oldPassword,
          newPassword: this.passwordForm.newPassword
        })

        if (res.data.code === 1) {
          this.$message.success('密码修改成功')
          // 清除需要修改密码的标记
          UserModule.ClearNeedChangePassword()
          // 重置表单
          this.resetForm()
          // 关闭弹窗
          this.dialogVisible = false
          this.$emit('success')
        } else {
          this.$message.error(res.data.msg || '密码修改失败')
        }
      } catch (error) {
        console.error('修改密码失败', error)
        let errorMsg = '密码修改失败，请稍后重试'
        if (error && (error as any).response && (error as any).response.data && (error as any).response.data.msg) {
          errorMsg = (error as any).response.data.msg
        } else if (error && (error as any).message) {
          errorMsg = (error as any).message
        }
        this.$message.error(errorMsg)
      } finally {
        this.submitting = false
      }
    })
  }

  private resetForm() {
    this.passwordForm = {
      oldPassword: '',
      newPassword: '',
      confirmPassword: ''
    }
    this.$nextTick(() => {
      const form = this.$refs.passwordForm as ElForm
      if (form) {
        form.clearValidate()
      }
    })
  }
}
